    backpagename: "By Therapeutic Class",
    backpagelink: "/products_therapeutic",

    innerMainHeading: "Esmax 20",
    innerComposition: "Esomeprazole USP",
    innerdata: [
      {
        innerHead: "COMPOSITION",
        innerData: ``,
        istable: false,
        table: {},
        islist: true,
        listData: [
          "Esmax® 20 Capsule: Each capsule contains 20 mg of Esomeprazole as Esomeprazole Magnesium Trihydrate USP in enteric coated pellets.",
          "Esmax® 20 Tablet: Each enteric coated tablet contains 20 mg of Esomeprazole as Esomeprazole Magnesium Trihydrate USP.",
          "Esmax® 40 Capsule: Each capsule contains 40 mg of Esomeprazole as Esomeprazole Magnesium Trihydrate USP in enteric coated pellets.",
        ],
      },
      {
        innerHead: "PHARMACOLOGY",
        innerData:
          "Esomeprazole is the s-isomer of Omeprazole. It is a proton pump inhibitor that suppresses gastric acid secretion by specific inhibition of the H+/K+-ATPase in the gastric parietal cell. By acting specifically on the proton pump, Esomeprazole blocks the final step in acid production, thus reducing gastric acidity. ",
        istable: false,
        table: {},
        islist: false,
        listData: ["", ""],
      },
      {
        innerHead: "INDICATIONS",
        innerData: ``,
        istable: false,
        table: {},
        islist: true,
        listData: [
          "Gastro-esophageal reflux disease (in the presence of erosive reflux esophagitis)",
          "Symptomatic treatment of Gastro-esophageal reflux disease (in the absence of esophagitis)",
          "NSAID associated gastric ulcer",
          "Duodenal ulcer associated with Helicobacter pylori",
          "Zollinger-Ellison syndrome",
        ],
      },
    ],
    innerdata1: [
      {
        innerHead: "DOSAGE AND ADMINISTRATION",
        innerData:
          "Esomeprazole should be taken one hour before meal. According to disease pattern, the recommended dosage & administration:",
        istable: false,
        table: {},
        islist: true,
        listData: [
          "Gastro-esophageal reflux disease (in the presence of erosive reflux esophagitis), 40 mg once daily for 4 weeks, continued for further 4 weeks if not fully healed or symptoms persist",
          "Symptomatic treatment of Gastro-esophageal reflux disease (in the absence of esophagitis), 20 mg once daily for up to 4 weeks, then 20 mg daily when required",
          "NSAID associated gastric ulcer, 20 mg once daily for 4-8 weeks",
          "Duodenal ulcer associated with Helicobacter pylori:",
        ],
      },
      {
        innerHead:
          "Recommended regimens for Helicobacter pylori eradication in adults",
        innerData: ``,
        istable: true,
        table: {
          headers: [
            "Acid suppressant (Antibacterial)",
            "Amoxicillin",
            "Clarithromycin",
            "Metronidazole",
          ],
          body: [
            [
              "Esomeprazole 20 mg twice daily",
              "1 g twice daily",
              `500 mg twice daily`,
              `-------------`,
            ],
            ["", `-------------`, "250 mg twice daily", `400 mg twice daily`],
          ],
        },
        islist: true,
        listData: [
          "Zollinger-Ellison syndrome, initially 40 mg twice daily, adjusted according to response; usual range 80-160 mg daily",
          "Usual pediatric dose for Gastro-esophageal reflux disease:Short-term treatment: 1-11 years old: 10 mg once daily for up to 8 weeks, 12-17 years old: 20-40 mg once daily for up to 8 weeks",
        ],
      },
      {
        innerHead: "SIDE EFFECTS",
        innerData:
          "Headache, flatulence, nausea, abdominal pain, diarrhea, dry mouth, dizziness/vertigo and constipation.",
        istable: false,
        table: {},
        islist: false,
        listData: ["", ""],
      },
      {
        innerHead: "CONTRAINDICATIONS",
        innerData:
          "Patients with known hypersensitivity to any component of the formulation. ",
        istable: false,
        table: {},
        islist: false,
        listData: ["", ""],
      },
      {
        innerHead: "PRECAUTIONS",
        innerData:
          "Symptomatic response to therapy with Esomeprazole does not preclude the presence of gastric malignancy. ",
        istable: false,
        table: {},
        islist: false,
        listData: ["", ""],
      },
      {
        innerHead: "USE IN SPECIAL GROUP",
        innerData:
          "Pregnancy: The safety of esomeprazole in pregnancy has not been established but esomeprazole can be used during pregnancy only if clearly needed.Lactation: The excretion of Esomeprazole in breast milk has not been studied. A decision should be made whether to discontinue nursing or to discontinue the drug, taking into account the importance of the drug to the mother.Pediatric use: Safety and efficacy have been established for the short-term treatment of GERD in patients of 1-17 years of age.",
        istable: false,
        table: {},
        islist: false,
        listData: ["", ""],
      },
      {
        innerHead: "DRUG INTERACTION",
        innerData:
          "Esomeprazole inhibits gastric acid secretion. Therefore, Esomeprazole may interfere with the absorption of drugs where gastric pH is an important determinant of bioavailability (e.g. Ketoconazole, Iron salts and Digoxin). ",
        istable: false,
        table: {},
        islist: false,
        listData: ["", ""],
      },
      {
        innerHead: "STORAGE",
        innerData:
          "Store in a cool (Below 30⁰ C Temp.) and dry place, away from light. Keep out of the reach of children.",
        istable: false,
        table: {},
        islist: false,
        listData: ["", ""],
      },
      {
        innerHead: "COMMERCIAL PACK",
        innerData: ``,
        istable: false,
        table: {},
        islist: true,
        listData: [
          "Esmax® 20 Capsule: Each box contains 10 x 10 capsules, in Alu-Alu blister pack.",
          "Esmax® 20 Tablet: Each box contains 6 x 10 capsules, in Alu-Alu blister pack.",
          "Esmax® 40 Capsule: Each box contains 5 x 4 capsules, in Alu-Alu blister pack.",
        ],
      },
    ],
    btn: "Read More",
    btnlink: "/prod_details",
    type: "Capsule",
